    /// @dev FeeM registration was under maintenance during deploy
    // SonicFeeMRegister.registerContract();
    StakingRewardsDistributor.initialize(
      staking_,
      globalOwner_,
      globalPause_,
      globalAccessList_
    );
  }
}
